"use strict";(self.webpackChunkplvacc_wiki=self.webpackChunkplvacc_wiki||[]).push([["6607"],{7735(a){a.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"safety-circular-readback-errors","metadata":{"permalink":"/blog/safety-circular-readback-errors","source":"@site/blog/2026-10-12-mentor-meeting-notes.md","title":"B\u0142\u0119dy w readbacku i hearbacku","description":"this post is an AI generated placeholder","date":"2026-10-12T00:00:00.000Z","tags":[{"inline":true,"label":"bezpiecze\u0144stwo","permalink":"/blog/tags/bezpieczenstwo"},{"inline":true,"label":"frazeologia","permalink":"/blog/tags/frazeologia"}],"readingTime":0.87,"hasTruncateMarker":false,"authors":[{"name":"Bartek","title":"Training Director","key":"bartek","page":null}],"frontMatter":{"slug":"safety-circular-readback-errors","title":"B\u0142\u0119dy w readbacku i hearbacku","authors":["bartek"],"tags":["bezpiecze\u0144stwo","frazeologia"]},"unlisted":false,"nextItem":{"title":"Dzia\u0142 Szkole\u0144 w liczbach: III kwarta\u0142 2026","permalink":"/blog/training-statistics-q3"}},"content":"**this post is an AI generated placeholder**\\n\\nW ostatnim kwartale instruktorzy zwr\xf3cili uwag\u0119 na powtarzaj\u0105cy si\u0119 problem w sesjach szkoleniowych: nieprawid\u0142owe powt\xf3rzenia (readbacki), kt\xf3re nie zosta\u0142y skorygowane.\\n\\n## Podsumowanie\\n\\nW przeanalizowanych sesjach kontrolerzy cz\u0119sto akceptowali niepe\u0142ne lub b\u0142\u0119dne powt\xf3rzenia, g\u0142\xf3wnie dotycz\u0105ce pasa, kursu i wysoko\u015Bci. \u017Badne z tych zdarze\u0144 nie doprowadzi\u0142o do utraty separacji, ale taki schemat jest znanym prekursorem powa\u017Cnych incydent\xf3w.\\n\\n## Typowe przyk\u0142ady\\n\\n- Pilot powtarza b\u0142\u0119dne oznaczenie pasa, a kontroler kontynuuje bez korekty\\n- Wysoko\u015B\u0107 powt\xf3rzona bez okre\u015Blenia \u201Epoziom lotu\u201D lub \u201Estopy\u201D\\n- Powt\xf3rzenie bez znaku wywo\u0142awczego, po kt\xf3rym nast\u0119puje niejednoznaczne \u201Eroger\u201D\\n\\n## Czynniki sprzyjaj\u0105ce\\n\\n- Du\u017Ce obci\u0105\u017Cenie prac\u0105, gdy kontroler planuje ju\u017C kolejne dzia\u0142anie\\n- Znany ruch, gdzie my\u015Blenie \u201Ena pewno powt\xf3rz\u0105 poprawnie\u201D prowadzi do rozlu\u017Anienia uwagi\\n- Szybkie tempo m\xf3wienia po obu stronach \u0142\u0105czno\u015Bci\\n\\n## Zalecane dzia\u0142ania\\n\\n1. Traktuj hearback (kontrol\u0119 powt\xf3rzenia) jako aktywne zadanie, a nie czynno\u015B\u0107 w tle\\n2. Poprawiaj ka\u017Cde odst\u0119pstwo natychmiast, u\u017Cywaj\u0105c pe\u0142nego znaku wywo\u0142awczego\\n3. Nie zast\u0119puj w\u0142a\u015Bciwego potwierdzenia s\u0142owem \u201Eroger\u201D\\n4. Mentorzy powinni uwzgl\u0119dnia\u0107 kontrol\u0119 powt\xf3rze\u0144 w ka\u017Cdym podsumowaniu sesji\\n\\n## Przypomnienie\\n\\nReadback jest siatk\u0105 bezpiecze\u0144stwa tylko wtedy, gdy kto\u015B naprawd\u0119 go s\u0142ucha."},{"id":"training-statistics-q3","metadata":{"permalink":"/blog/training-statistics-q3","source":"@site/blog/2026-10-02-training-statistics.md","title":"Dzia\u0142 Szkole\u0144 w liczbach: III kwarta\u0142 2026","description":"this post is an AI generated placeholder","date":"2026-10-02T00:00:00.000Z","tags":[{"inline":true,"label":"statystyki","permalink":"/blog/tags/statystyki"},{"inline":true,"label":"szkolenia","permalink":"/blog/tags/szkolenia"},{"inline":true,"label":"raport","permalink":"/blog/tags/raport"}],"readingTime":0.82,"hasTruncateMarker":false,"authors":[{"name":"Bartek","title":"Training Director","key":"bartek","page":null}],"frontMatter":{"slug":"training-statistics-q3","title":"Dzia\u0142 Szkole\u0144 w liczbach: III kwarta\u0142 2026","authors":["bartek"],"tags":["statystyki","szkolenia","raport"]},"unlisted":false,"prevItem":{"title":"B\u0142\u0119dy w readbacku i hearbacku","permalink":"/blog/safety-circular-readback-errors"},"nextItem":{"title":"SIDs and STARs Explained","permalink":"/blog/what-is-a-sid-and-star"}},"content":"**this post is an AI generated placeholder**\\n\\nKr\xf3tkie spojrzenie na to, jak przebiega\u0142y szkolenia mi\u0119dzy lipcem a wrze\u015Bniem.\\n\\n\\n*Wszystkie poni\u017Csze dane s\u0105 przyk\u0142adowe. Zast\u0105p je prawdziwymi.*\\n\\n## Najwa\u017Cniejsze liczby\\n\\n| Wska\u017Anik | II kw. | III kw. |\\n|---|---|---|\\n| Nowi przyj\u0119ci kursanci | 14 | 18 |\\n| Aktywni mentorzy | 8 | 10 |\\n| Przeprowadzone sesje szkoleniowe | 112 | 134 |\\n| Podej\u015Bcia do egzaminu praktycznego | 21 | 25 |\\n| Zdawalno\u015B\u0107 egzamin\xf3w | 71% | 76% |\\n\\n## Co zwraca uwag\u0119\\n\\n- **Wi\u0119cej kursant\xf3w, ni\u017C mentorzy mog\u0105 komfortowo prowadzi\u0107.** Na jednego mentora przypada obecnie \u015Brednio oko\u0142o 1,8 aktywnego kursanta.\\n- **Zdawalno\u015B\u0107 wzros\u0142a**, g\u0142\xf3wnie dzi\u0119ki li\u015Bcie kontrolnej przed egzaminem wprowadzonej w lipcu.\\n- **Wi\u0119kszo\u015B\u0107 niezdanych egzamin\xf3w** wynika\u0142a z problem\xf3w z planowaniem ruchu i koordynacj\u0105, a nie z frazeologii.\\n\\n## \u015Aredni czas do uzyskania uprawnie\u0144\\n\\nKursanci potrzebowali \u015Brednio oko\u0142o 11 tygodni na uko\u0144czenie pierwszego etapu wie\u017Cy, czyli nieco mniej ni\u017C w poprzednim kwartale.\\n\\n## Cele na IV kwarta\u0142\\n\\n- Pozyska\u0107 dw\xf3ch kolejnych mentor\xf3w\\n- Skr\xf3ci\u0107 czas oczekiwania mi\u0119dzy zg\u0142oszeniem a pierwsz\u0105 sesj\u0105\\n- Opublikowa\u0107 kr\xf3tki przewodnik po planowaniu ruchu, oparty na najcz\u0119stszych uwagach egzaminator\xf3w\\n\\nDzi\u0119kujemy wszystkim mentorom i kursantom za prac\u0119 w tym kwartale."},{"id":"what-is-a-sid-and-star","metadata":{"permalink":"/blog/what-is-a-sid-and-star","source":"@site/blog/2026-09-28-readback-errors.md","title":"SIDs and STARs Explained","description":"this post is an AI generated placeholder","date":"2026-09-28T00:00:00.000Z","tags":[{"inline":true,"label":"procedures","permalink":"/blog/tags/procedures"},{"inline":true,"label":"ifr","permalink":"/blog/tags/ifr"}],"readingTime":0.56,"hasTruncateMarker":false,"authors":[{"name":"Bartek","title":"Training Director","key":"bartek","page":null}],"frontMatter":{"slug":"what-is-a-sid-and-star","title":"SIDs and STARs Explained","authors":["bartek"],"tags":["procedures","ifr"]},"unlisted":false,"prevItem":{"title":"Dzia\u0142 Szkole\u0144 w liczbach: III kwarta\u0142 2026","permalink":"/blog/training-statistics-q3"}},"content":"**this post is an AI generated placeholder**\\n\\nSIDs and STARs are published routes that standardize how aircraft leave and arrive at busy airports.\\n\\n\\nA **SID** (Standard Instrument Departure) guides an aircraft from the runway to the en-route airway network. A **STAR** (Standard Terminal Arrival Route) does the reverse, leading it from the airway network toward the approach.\\n\\nThe benefits are practical:\\n\\n- Less radio traffic, since the route is already known\\n- Predictable flows that keep departures and arrivals apart\\n- Built-in noise abatement and terrain clearance\\n\\nInstead of dictating every turn, a controller can say \\"cleared via the SID\\" or \\"descend via the STAR\\", and both sides know exactly what to expect."}]}}')}}]);